// 新供给许可和原责任算法薄接；临时政策/读借用绝不挂入World或跨下一次commit。
#include "affairs_issued_supply.hpp"
#include <limits>
namespace hanmo::resident {
Status reconcile_affairs_with_issued_supply(CommonStore& common,AffairsState& state,const AffairsCatalog& authored,TaskState& tasks,const TaskCatalog& catalog,const std::vector<SupplyObservation>& old_observations,const DynamicResultRead& results,Integer tick,const EconomicSupplyPolicyRead& read,const TaskExecutionServices* execution,const std::vector<EconomicSupplySuspension>* supply_suspensions,const DynamicStepInput* phase){
 if(phase){if(common.tick()==std::numeric_limits<Integer>::max()||phase->from_tick!=common.tick()||phase->to_tick!=common.tick()+1||tick!=phase->to_tick)return common_failure("AffairsCalendarPhaseMismatch");}else if(tick!=common.tick())return common_failure("AffairsTickMismatch");auto projection=read_affairs_issued_supply_projection(common,authored,catalog,&read,phase);if(!projection.ok)return {false,{},projection.error};std::vector<SupplyObservation> observations=old_observations;
 // 新观察必须由唯一typed投影加入，禁止caller重复投喂或伪造原域source_key。
 for(const auto& observation:old_observations)if(projection.value.issued.find(observation.source_key)||observation.source_key.rfind("economic_supply_policy:",0)==0)return common_failure("UnexpectedIssuedSupplyObservation",observation.source_key);
 observations.insert(observations.end(),projection.value.fresh_observations.begin(),projection.value.fresh_observations.end());return reconcile_affairs(common,state,projection.value.catalog,tasks,observations,results,tick,execution,supply_suspensions,&projection.value.unavailable_policy_ids,phase);
}
Status publish_need_offers_with_issued_supply(CommonStore& common,AffairsState& state,const AffairsCatalog& authored,TaskState& tasks,const TaskCatalog& catalog,Integer tick,const EconomicSupplyPolicyRead& read,const DynamicStepInput* phase){
 if(phase){if(common.tick()==std::numeric_limits<Integer>::max()||phase->from_tick!=common.tick()||phase->to_tick!=common.tick()+1||tick!=phase->to_tick)return common_failure("AffairsCalendarPhaseMismatch");}else if(tick!=common.tick())return common_failure("AffairsTickMismatch");auto projection=read_affairs_issued_supply_projection(common,authored,catalog,&read,phase);if(!projection.ok)return {false,{},projection.error};auto paused=project_affairs_issued_supply_suspensions(common,state,tasks,projection.value);if(!paused.ok)return paused;return publish_need_offers(common,state,projection.value.catalog,tasks,catalog,tick);
}
Status validate_affairs_with_issued_supply(const CommonStore& common,const AffairsState& state,const AffairsCatalog& authored,const TaskState& tasks,const TaskCatalog& catalog,const EconomicSupplyPolicyRead& read,const DynamicResultRead* results,const FiscalNeedValidationRead* fiscal_needs,const CohortWageNeedValidationRead* cohort_wages,const std::vector<EconomicSupplySuspension>* supply_suspensions,const DynamicStepInput* phase,const WorldMoment* actual_moment){
 auto projection=read_affairs_issued_supply_projection(common,authored,catalog,&read,phase);if(!projection.ok)return {false,{},projection.error};auto history=validate_affairs_issued_supply_history(common,state,projection.value,&read,phase);if(!history.ok)return history;return validate_affairs(common,state,projection.value.catalog,tasks,results,fiscal_needs,cohort_wages,supply_suspensions,&projection.value.unavailable_policy_ids,actual_moment);
}
Status project_affairs_issued_supply_in_candidate(const CommonStore& common,AffairsState& state,const AffairsCatalog& authored,TaskState& tasks,const TaskCatalog& catalog,const EconomicSupplyPolicyRead& read,const DynamicStepInput* phase){auto projection=read_affairs_issued_supply_projection(common,authored,catalog,&read,phase);if(!projection.ok)return {false,{},projection.error};return project_affairs_issued_supply_suspensions(common,state,tasks,projection.value);}
Outcome<std::vector<OpportunityView>> query_opportunities_with_issued_supply(const CommonStore& common,const AffairsState& state,const TaskState& tasks,const KnownSubjectView& known,const EconomicSupplyPolicyRead* read){return filter_affairs_issued_supply_opportunities(common,state,tasks,query_opportunities(state,tasks,known),read);}
}
